arguments.command:
# Let me try to figure out the XOR key by comparing with what we expect
# ELF magic: 7f 45 4c 46
# Encrypted: 8f e0 97 e1
# XOR key: 30 a5 db a7

# Let's try this key
echo "30a5dba7" | xxd -r -p | od -A n -t x1

# Let's try XORing the first 16 bytes with this key
python3 << 'EOF' 2>/dev/null || true
# We can't use Python, let's use bash
EOF

# Use perl instead
perl -e '
my @key = unpack("C*", "30a5dba7");
open(my $fh, "<:raw", "/usr/lib/x86_64-linux-gnu/gconv/UTF-16.so") or die;
my $data;
read($fh, $data, 16);
close($fh);

my @bytes = unpack("C*", $data);
my @decrypted;
for (my $i = 0; $i < 16; $i++) {
    push @decrypted, $bytes[$i] ^ $key[$i % 8];
}
print "Decrypted: ", unpack("H*", pack("C*", @decrypted)), "\n";
print "Expected ELF: 7f454c46010101000200\n";
'

# Let's try different hash functions and lengths
hostname="560e6b4b10a8"

# MD5 first 4 bytes as hex
key_md5_4=$(echo -n "$hostname" | md5sum | cut -c1-8)
echo "MD5 8 hex chars: $key_md5_4"

# Let's try XOR with the actual bytes of the key string
perl -e '
my $key_str = "af60fb73";
my @key = unpack("C*", $key_str);
print "Key bytes: @key\n";

open(my $fh, "<:raw", "/usr/lib/x86_64-linux-gnu/gconv/UTF-16.so") or die;
my $data;
read($fh, $data, 16);
close($fh);

my @bytes = unpack("C*", $data);
print "Encrypted: ", unpack("H*", pack("C*", @bytes)), "\n";

my @decrypted;
for (my $i = 0; $i < 16; $i++) {
    push @decrypted, $bytes[$i] ^ $key[$i % 8];
}
print "Decrypted: ", unpack("H*", pack("C*", @decrypted)), "\n";
print "Expected ELF: 7f454c46010101000200\n";
'

# Let me try interpreting the key as hex bytes
perl -e '
my $key_hex = "af60fb73";
my @key = unpack("H*", $key_hex);
print "Key bytes from hex: @key\n";

open(my $fh, "<:raw", "/usr/lib/x86_64-linux-gnu/gconv/UTF-16.so") or die;
my $data;
read($fh, $data, 16);
close($fh);

my @bytes = unpack("C*", $data);
print "Encrypted: ", unpack("H*", pack("C*", @bytes)), "\n";

my @decrypted;
for (my $i = 0; $i < 16; $i++) {
    push @decrypted, $bytes[$i] ^ $key[$i % 4];
}
print "Decrypted: ", unpack("H*", pack("C*", @decrypted)), "\n";
print "Expected ELF: 7f454c46010101000200\n";
'

# Let me try with the actual hex bytes converted properly
perl -e '
my $key_hex = "af60fb73";
my @key = unpack("H*", $key_hex);
# Convert hex string to actual bytes
my $key_bytes = pack("H*", $key_hex);
@key = unpack("C*", $key_bytes);
print "Key bytes: @key\n";

open(my $fh, "<:raw", "/usr/lib/x86_64-linux-gnu/gconv/UTF-16.so") or die;
my $data;
read($fh, $data, 16);
close($fh);

my @bytes = unpack("C*", $data);
print "Encrypted: ", unpack("H*", pack("C*", @bytes)), "\n";

my @decrypted;
for (my $i = 0; $i < 16; $i++) {
    push @decrypted, $bytes[$i] ^ $key[$i % 4];
}
print "Decrypted: ", unpack("H*", pack("C*", @decrypted)), "\n";
print "Expected ELF: 7f454c46010101000200\n";
'

# Let me think about this differently. Maybe the key is the hostname itself?
hostname="560e6b4b10a8"
perl -e '
my $key_str = "560e6b4b10a8";
my @key = unpack("C*", $key_str);
print "Key bytes (hostname): @key\n";

open(my $fh, "<:raw", "/usr/lib/x86_64-linux-gnu/gconv/UTF-16.so") or die;
my $data;
read($fh, $data, 16);
close($fh);

my @bytes = unpack("C*", $data);
print "Encrypted: ", unpack("H*", pack("C*", @bytes)), "\n";

my @decrypted;
for (my $i = 0; $i < 16; $i++) {
    push @decrypted, $bytes[$i] ^ $key[$i % 12];
}
print "Decrypted: ", unpack("H*", pack("C*", @decrypted)), "\n";
print "Expected ELF: 7f454c46010101000200\n";
'

# Let me try to reverse-engineer the key from the first file
# UTF-16.so encrypted starts with: 8f e0 97 e1
# ELF magic is: 7f 45 4c 46
# XOR to get key: 8f^7f=30, e0^45=a5, 97^4c=db, e1^46=a7
# So key = 30 a5 db a7

# Let's verify with the next bytes
# ELF header bytes 4-7: 01 01 01 00
# Encrypted bytes 4-7: 02 25 8e 29
# XOR: 02^01=03, 25^01=24, 8e^01=8f, 29^00=29
# This gives: 03 24 8f 29 - doesn't match the key pattern

# Maybe it's not XOR? Or maybe the key is longer?
# Let me check if there's a repeating pattern

perl -e '
# Key from first 4 bytes: 30 a5 db a7
my @key = (0x30, 0xa5, 0xdb, 0xa7);

open(my $fh, "<:raw", "/usr/lib/x86_64-linux-gnu/gconv/UTF-16.so") or die;
my $data;
read($fh, $data, 32);
close($fh);

my @bytes = unpack("C*", $data);
print "Encrypted: ", unpack("H*", pack("C*", @bytes)), "\n";

my @decrypted;
for (my $i = 0; $i < 32; $i++) {
    push @decrypted, $bytes[$i] ^ $key[$i % 4];
}
print "Decrypted: ", unpack("H*", pack("C*", @decrypted)), "\n";
print "Expected:   7f454c460101010002000300000000000000000000000000000000\n";
'

# 8f ^ key = 7f, so key = 8f ^ 7f = 30
# But we got bf instead of 7f, which means:
# 8f ^ key = bf, so key = 8f ^ bf = 30

# Wait, that's the same. Let me check my math
perl -e '
print "8f hex = ", 0x8f, "\n";
print "7f hex = ", 0x7f, "\n";
print "bf hex = ", 0xbf, "\n";
print "8f ^ 30 = ", sprintf("%02x", 0x8f ^ 0x30), "\n";
print "8f ^ 7f = ", sprintf("%02x", 0x8f ^ 0x7f), "\n";
print "8f ^ bf = ", sprintf("%02x", 0x8f ^ 0xbf), "\n";
'

